let bars, minWH, len, pallete, pInd;

function setup() {
	createCanvas(windowWidth, windowHeight);
	minWH = max(width, height) * 0.5;
	len = minWH * 0.35;
	pixelDensity(1);
	frameRate(60);
	strokeWeight(len * 0.02);
	noFill();

	// generate bars
	bars = [];
	for (let i = 0; i < 25; i++) {
		const a = random(TWO_PI);
		const r = minWH - random(random(len, minWH - len));
		bars.push({a, r, l: len});
	}

	// define colors
	palette = [
		["white", "red"],
		[color(255), lerpColor(color(255), color(32, 160, 192), 0.5), color(32, 160, 192), lerpColor(color(255), color(192, 32, 160), 0.5), color(192, 32, 160), color(192, 32, 160)],
		["white", "red","red", "green", "blue", "blue"]
	];
	pInd = floor(random(palette.length));
}

function getColor(v) {
	return palette[pInd][floor(palette[pInd].length * v)];
}

function windowResized() {
	setup();
}
function mouseClicked() {
	if (mouseButton === LEFT) setup();
}

function draw() {
	background(0, 48);
	translate(width / 2, height / 2)

	for (let b of bars) {
		push()
		var a = b.a + sin(frameCount * 0.05 * fract(b.a) * abs(sin(b.a + b.r)));
		const x = cos(a) * b.r;
		const y = sin(a) * b.r;

		stroke(getColor(noise(b.a * b.r, frameCount * 0.01)));

		translate(x, y);
		rotate(a)
		line(-b.l * 0.5, 0, b.l * 0.5, 0)
		pop();
	}
}
